<script setup>
import { computed, inject, ref } from 'vue';
import CouponFields from '../components/forms/CouponFields.vue';
import AdminGameWallSponsors from '../../components/admin/AdminGameWallSponsors.vue';
const props = defineProps({ section: { type: String, required: true } });
const c = inject('admin-v2');
const query = ref('');
const expandedPlayer = ref(0);
const search = items => items.filter(item => Object.values(item).filter(value => typeof value === 'string').join(' ').toLowerCase().includes(query.value.toLowerCase()));
const filteredTeams = computed(() => search(c.teams));
const filteredAdmins = computed(() => search(c.admins));
const filteredPartners = computed(() => search(c.partners));
const filteredSponsors = computed(() => search(c.sponsors));
const filteredCoupons = computed(() => search(c.coupons));
const remove = (title, message, key, fn) => c.confirmAction(title, message, () => c.run(key, fn, 'Elemento eliminato.'));
const save = (key, fn) => c.run(key, fn, 'Modifiche salvate.');
</script>

<template>
  <div class="v2-stack v2-entities">
    <div v-if="section !== 'players'" class="v2-toolbar"><label class="v2-field v2-search">Cerca nell’elenco<input v-model="query" type="search" placeholder="Cerca per nome…" /></label><button class="v2-button" :disabled="c.busy('entities-refresh')" @click="c.run('entities-refresh', c.refreshWorkspace)">{{ c.busy('entities-refresh') ? 'Aggiornamento…' : 'Aggiorna dati' }}</button></div>

    <template v-if="section === 'teams'">
      <section class="v2-panel"><div class="v2-section-heading"><div><h2>Aggiungi una squadra</h2><p class="v2-muted">Le squadre collegano partite e giocatori della società.</p></div></div><form class="v2-toolbar" @submit.prevent="save('create-team', c.createTeam)"><label class="v2-field v2-grow">Nome squadra<input v-model.trim="c.newTeamName" placeholder="Es. Prima squadra" required /></label><button class="v2-button v2-primary" :disabled="c.busy('create-team')">Aggiungi squadra</button></form></section>
      <section class="v2-panel"><h2>Squadre <span class="v2-badge">{{ c.teams.length }}</span></h2><div v-if="filteredTeams.length" class="v2-table-wrap"><table class="v2-table"><thead><tr><th scope="col">Squadra</th><th scope="col">Identificativo</th><th scope="col">Azioni</th></tr></thead><tbody><tr v-for="team in filteredTeams" :key="team.id"><th scope="row">{{ team.name }}</th><td>#{{ team.id }}</td><td><button class="v2-button v2-danger" :disabled="c.busy(`team-${team.id}`)" @click="remove('Eliminare la squadra?', `Confermi l’eliminazione di ${team.name}?`, `team-${team.id}`, () => c.deleteTeam(team.id))">Elimina</button></td></tr></tbody></table></div><p v-else class="v2-empty">{{ c.teams.length ? 'Nessuna squadra corrisponde alla ricerca.' : 'Aggiungi la prima squadra per preparare gli eventi.' }}</p></section>
    </template>

    <template v-else-if="section === 'admins'">
      <section class="v2-panel"><h2>Nuovo amministratore</h2><p class="v2-muted">Crea le credenziali di accesso per il personale della società.</p><form class="v2-grid v2-grid-3" @submit.prevent="save('create-admin', c.createAdmin)"><label class="v2-field">Nome utente<input v-model.trim="c.newAdmin.username" autocomplete="off" required /></label><label class="v2-field">Password<input v-model="c.newAdmin.password" type="password" autocomplete="new-password" required /></label><label class="v2-field">Ruolo<input v-model.trim="c.newAdmin.role" placeholder="Es. staff" /><small>I permessi sono applicati dal sistema esistente.</small></label><div><button class="v2-button v2-primary" :disabled="c.busy('create-admin')">Crea amministratore</button></div></form></section>
      <section class="v2-panel"><h2>Accessi amministrativi <span class="v2-badge">{{ c.admins.length }}</span></h2><div v-if="filteredAdmins.length" class="v2-table-wrap"><table class="v2-table"><thead><tr><th scope="col">Utente</th><th scope="col">Ruolo</th><th scope="col">Azioni</th></tr></thead><tbody><tr v-for="admin in filteredAdmins" :key="admin.id"><th scope="row">{{ admin.username }}</th><td><span class="v2-badge">{{ admin.role || 'staff' }}</span></td><td><button class="v2-button v2-danger" :disabled="c.busy(`admin-${admin.id}`)" @click="remove('Revocare l’accesso?', `L’account ${admin.username} verrà eliminato.`, `admin-${admin.id}`, () => c.deleteAdmin(admin.id))">Elimina</button></td></tr></tbody></table></div><p v-else class="v2-empty">{{ c.admins.length ? 'Nessun account corrisponde alla ricerca.' : 'Nessun amministratore presente nell’elenco.' }}</p></section>
    </template>

    <template v-else-if="section === 'partners'">
      <section class="v2-panel"><h2>Nuovo partner</h2><p class="v2-muted">I partner accedono con credenziali dedicate per convalidare i coupon.</p><form class="v2-grid v2-grid-3" @submit.prevent="save('create-partner', c.createPartner)"><label class="v2-field">Nome partner<input v-model.trim="c.newPartner.name" placeholder="Es. Bar dello stadio" /></label><label class="v2-field">Nome utente<input v-model.trim="c.newPartner.username" autocomplete="off" required /></label><label class="v2-field">Password<input v-model="c.newPartner.password" type="password" autocomplete="new-password" required /></label><div><button class="v2-button v2-primary" :disabled="c.busy('create-partner')">Crea partner</button></div></form></section>
      <section class="v2-panel"><h2>Partner convenzionati <span class="v2-badge">{{ c.partners.length }}</span></h2><div v-if="filteredPartners.length" class="v2-stack"><article v-for="partner in filteredPartners" :key="partner.id" class="v2-entity-row"><div><h3>{{ partner.displayName || partner.username }}</h3><p class="v2-muted">{{ partner.username }}<span v-if="partner.createdAtLabel"> · Creato il {{ partner.createdAtLabel }}</span></p></div><form class="v2-toolbar" @submit.prevent="save(`partner-${partner.id}`, () => c.updatePartnerPassword(partner))"><label class="v2-field v2-grow">Nuova password<input v-model="partner.newPassword" type="password" autocomplete="new-password" /></label><button class="v2-button" :disabled="!partner.newPassword || c.busy(`partner-${partner.id}`)">Aggiorna password</button><button type="button" class="v2-button v2-danger" :disabled="c.busy(`partner-delete-${partner.id}`)" @click="remove('Eliminare il partner?', `Confermi l’eliminazione di ${partner.username}?`, `partner-delete-${partner.id}`, () => c.deletePartner(partner.id))">Elimina</button></form></article></div><p v-else class="v2-empty">{{ c.partners.length ? 'Nessun partner corrisponde alla ricerca.' : 'Crea il primo partner per distribuire coupon.' }}</p></section>
    </template>

    <template v-else-if="section === 'players'">
      <form class="v2-stack" @submit.prevent="save('save-players', c.savePlayers)">
      <section class="v2-panel"><div class="v2-section-heading"><div><h2>Roster e convocazioni</h2><p class="v2-muted">Gestisci fino a {{ c.playerSlotCount }} giocatori. Apri una scheda per modificarne i dettagli.</p></div><span class="v2-badge">{{ c.players.length }} giocatori salvati</span></div><p v-if="!c.teams.length" class="v2-notice">Aggiungi almeno una squadra per assegnare i giocatori.</p><p v-if="c.playerOverflow.length" class="v2-notice">Il database contiene {{ c.playerOverflow.length }} giocatori oltre il limite: verranno rimossi al prossimo salvataggio.</p><label class="v2-field v2-roster-schema">Schema della pagina di voto<select v-model.number="c.rosterSchema"><option :value="12">12 giocatori</option><option :value="13">13 giocatori</option><option :value="14">14 giocatori</option></select></label></section>
      <div class="v2-roster-list"><article v-for="(slot, index) in c.playerSlots" :key="index" class="v2-panel v2-player"><button type="button" class="v2-player-heading" :aria-expanded="expandedPlayer === index" :aria-controls="`v2-player-${index}`" @click="expandedPlayer = expandedPlayer === index ? -1 : index"><span class="v2-player-avatar"><img v-if="slot.image_preview" :src="slot.image_preview" alt="" /><span v-else>{{ slot.jersey_number || String(index + 1).padStart(2, '0') }}</span></span><span class="v2-grow"><strong>{{ [slot.first_name, slot.last_name].filter(Boolean).join(' ') || `Giocatore ${index + 1}` }}</strong><small>{{ slot.role || 'Profilo da completare' }}<template v-if="slot.team_id"> · {{ c.teamName(slot.team_id) }}</template></small></span><span class="v2-badge">{{ slot.is_called_up ? 'Convocato' : 'Non convocato' }}</span><span aria-hidden="true">{{ expandedPlayer === index ? '−' : '+' }}</span></button><div v-show="expandedPlayer === index" :id="`v2-player-${index}`" class="v2-stack v2-player-fields"><div class="v2-grid v2-grid-3"><label class="v2-field">Nome<input v-model.trim="slot.first_name" /></label><label class="v2-field">Cognome<input v-model.trim="slot.last_name" /></label><label class="v2-field">Ruolo<input v-model.trim="slot.role" placeholder="Es. Schiacciatore" /></label><label class="v2-field">Numero maglia<input v-model="slot.jersey_number" type="number" min="0" inputmode="numeric" /></label><label class="v2-field">Squadra<select v-model.number="slot.team_id"><option :value="0">Seleziona squadra</option><option v-for="team in c.teams" :key="team.id" :value="team.id">{{ team.name }}</option></select></label><label class="v2-check"><input v-model="slot.is_called_up" type="checkbox" />Convocato per la pagina di voto</label></div><div class="v2-grid v2-grid-2"><label class="v2-field">URL immagine<input v-model.trim="slot.image_url" type="url" placeholder="https://…" @input="c.handlePlayerUrlChange(index)" /></label><label class="v2-field">Oppure carica una foto<input type="file" accept="image/*" @change="c.run(`player-image-${index}`, () => c.handlePlayerImageChange(index, $event))" /></label></div><div v-if="slot.image_preview" class="v2-media-preview"><img :src="slot.image_preview" :alt="`Anteprima di ${slot.first_name || 'giocatore'}`" /><button type="button" class="v2-button" @click="c.removePlayerImage(index)">Rimuovi foto</button></div><p class="v2-muted">Per eliminare un giocatore svuota i suoi campi e salva il roster.</p></div></article></div>
      <section class="v2-panel v2-save-bar"><p v-if="c.playerSaveError" class="v2-error" role="alert">{{ c.playerSaveError }}</p><p v-if="c.playerSaveMessage" role="status" class="v2-success">{{ c.playerSaveMessage }}</p><div class="v2-toolbar"><button type="button" class="v2-button" :disabled="c.isSavingPlayers" @click="c.confirmAction('Ripristinare il roster?', 'Le modifiche locali verranno sostituite con gli ultimi dati salvati.', c.restorePlayerSlots)">Ripristina dati salvati</button><button type="submit" class="v2-button v2-primary" :disabled="c.isSavingPlayers || c.busy('save-players')">{{ c.isSavingPlayers ? 'Salvataggio…' : 'Salva roster e convocazioni' }}</button></div></section>
      </form>
    </template>

    <template v-else-if="section === 'sponsors'">
      <AdminGameWallSponsors class="v2-panel" :auth-headers="c.authHeaders" :sponsors="c.sponsors" :run="c.run" />
      <section class="v2-panel"><h2>Visibilità nell’arena</h2><p class="v2-muted">Mostra i primi sponsor nell’ordine delle loro posizioni. Massimo {{ c.maxSponsors }} sponsor.</p><label class="v2-field">Sponsor visibili: {{ c.desiredActiveSponsorCount }} / {{ c.maxSponsors }}<input v-model.number="c.desiredActiveSponsorCount" type="range" min="0" :max="c.sponsorSliderMax" :disabled="!c.sponsors.length || c.isApplyingSponsorCount" @change="save('sponsor-visibility', c.applyActiveSponsorCount)" /></label></section>
      <details class="v2-panel" :open="!c.sponsors.length"><summary class="v2-details-title">Aggiungi sponsor <span class="v2-badge">{{ c.sponsors.length }}/{{ c.maxSponsors }}</span></summary><form class="v2-stack v2-details-content" @submit.prevent="save('create-sponsor', c.createSponsor)"><div class="v2-grid v2-grid-2"><label class="v2-field">Nome sponsor<input v-model.trim="c.newSponsor.name" placeholder="Es. Partner ufficiale" /></label><label class="v2-field">Nome nei report<input v-model.trim="c.newSponsor.reportName" placeholder="Etichetta per i report" /></label><label class="v2-field">Sito web facoltativo<input v-model.trim="c.newSponsor.linkUrl" type="url" placeholder="https://…" /></label><label class="v2-field">Logo sponsor<input type="file" accept="image/*" @change="c.run('new-sponsor-image', () => c.handleNewSponsorLogoChange($event))" /></label></div><div v-if="c.newSponsor.logoData" class="v2-media-preview"><img :src="c.newSponsor.logoData" alt="Anteprima logo del nuovo sponsor" /></div><div><button class="v2-button v2-primary" :disabled="c.isCreatingSponsor || c.sponsors.length >= c.maxSponsors">{{ c.isCreatingSponsor ? 'Salvataggio…' : 'Aggiungi sponsor' }}</button></div></form></details>
      <p v-if="!filteredSponsors.length" class="v2-empty">{{ c.sponsors.length ? 'Nessuno sponsor corrisponde alla ricerca.' : 'Nessuno sponsor configurato.' }}</p><article v-for="sponsor in filteredSponsors" :key="sponsor.id" class="v2-panel"><div class="v2-section-heading"><div class="v2-toolbar"><div class="v2-sponsor-logo"><img v-if="sponsor.logoData" :src="sponsor.logoData" :alt="`Logo ${sponsor.name || 'sponsor'}`" /><span v-else>Logo assente</span></div><div><h2>{{ sponsor.name || `Sponsor ${sponsor.position}` }}</h2><p class="v2-muted">Posizione {{ sponsor.position }} · {{ sponsor.isActive ? 'Visibile' : 'Nascosto' }}</p></div></div><span class="v2-badge">{{ sponsor.isActive ? 'Attivo' : 'Nascosto' }}</span></div><form class="v2-stack" @submit.prevent="save(`sponsor-${sponsor.id}`, () => c.updateSponsorEntry(sponsor))"><div class="v2-grid v2-grid-2"><label class="v2-field">Nome<input v-model.trim="sponsor.name" /></label><label class="v2-field">Nome nei report<input v-model.trim="sponsor.reportName" /></label><label class="v2-field">Sito web<input v-model.trim="sponsor.linkUrl" type="url" /></label><label class="v2-field">Sostituisci logo<input type="file" accept="image/*" @change="c.run(`sponsor-image-${sponsor.id}`, () => c.handleSponsorLogoChange($event, sponsor))" /></label></div><div class="v2-toolbar"><button class="v2-button v2-primary" :disabled="c.sponsorBeingUpdated === sponsor.id">Salva sponsor</button><button class="v2-button v2-danger" type="button" :disabled="c.sponsorBeingDeleted === sponsor.id" @click="remove('Eliminare lo sponsor?', `Confermi l’eliminazione di ${sponsor.name || 'questo sponsor'}?`, `sponsor-delete-${sponsor.id}`, () => c.deleteSponsorEntry(sponsor.id))">Elimina</button></div></form></article>
    </template>

    <template v-else-if="section === 'coupons'">
      <p v-if="!c.partners.length" class="v2-notice">Aggiungi almeno un partner dalla sezione Partner per creare coupon.</p><p v-if="c.couponError" class="v2-error" role="alert">{{ c.couponError }}</p><p v-if="c.couponSuccess" class="v2-success" role="status">{{ c.couponSuccess }}</p><details class="v2-panel" :open="!c.coupons.length"><summary class="v2-details-title">Crea un coupon</summary><form class="v2-stack v2-details-content" @submit.prevent="save('create-coupon', c.createCoupon)"><CouponFields :draft="c.newCoupon" identity="new" /><div><button class="v2-button v2-primary" :disabled="c.isCreatingCoupon || !c.partners.length">{{ c.isCreatingCoupon ? 'Creazione…' : 'Crea coupon' }}</button></div></form></details>
      <p v-if="!filteredCoupons.length" class="v2-empty">{{ c.coupons.length ? 'Nessun coupon corrisponde alla ricerca.' : 'Nessun coupon configurato.' }}</p><details v-for="coupon in filteredCoupons" :key="coupon.id" class="v2-panel"><summary class="v2-details-title"><span>{{ coupon.title }}</span><span class="v2-badge">{{ c.getCouponStatusLabel(coupon.status) }}</span></summary><div class="v2-coupon-metrics"><span><strong>{{ coupon.totalViews }}</strong> visualizzazioni</span><span><strong>{{ coupon.totalClaims }}</strong> richieste</span><span><strong>{{ coupon.totalRedemptions }}</strong> utilizzi</span></div><form class="v2-stack v2-details-content" @submit.prevent="save(`coupon-${coupon.id}`, () => c.updateCouponEntry(coupon))"><CouponFields :draft="coupon" :identity="String(coupon.id)" /><div class="v2-toolbar"><button class="v2-button v2-primary" :disabled="c.couponBeingSaved === coupon.id">{{ c.couponBeingSaved === coupon.id ? 'Salvataggio…' : 'Salva coupon' }}</button><button class="v2-button v2-danger" type="button" :disabled="c.couponBeingDeleted === coupon.id" @click="remove('Eliminare il coupon?', `Confermi l’eliminazione di ${coupon.title}?`, `coupon-delete-${coupon.id}`, () => c.deleteCouponEntry(coupon.id))">Elimina</button></div></form></details>
    </template>
  </div>
</template>

<style scoped>
.v2-entities>.v2-panel>h2{margin-bottom:8px}.v2-entities>.v2-panel>p+.v2-grid,.v2-entities>.v2-panel>h2+.v2-table-wrap,.v2-entities>.v2-panel>h2+.v2-stack{margin-top:20px}.v2-entity-row form{margin-top:18px}.v2-entities .v2-table{table-layout:fixed}.v2-entities .v2-table th,.v2-entities .v2-table td{white-space:normal;overflow-wrap:anywhere}.v2-search{max-width:430px;flex:1}.v2-grow{flex:1;min-width:0}.v2-section-heading{display:flex;align-items:center;justify-content:space-between;gap:16px;margin-bottom:20px}.v2-entity-row{padding:18px;border:1px solid var(--v2-line,#dce2e9);border-radius:12px}.v2-entity-row h3{margin:0}.v2-details-title{font-size:17px;font-weight:650;cursor:pointer;min-height:44px;line-height:1.6}.v2-details-title .v2-badge{margin-left:10px}.v2-details-content{padding-top:20px}.v2-roster-list{display:grid;gap:12px}.v2-player{padding:0!important;overflow:hidden}.v2-player-heading{width:100%;display:flex;align-items:center;gap:14px;padding:18px;border:0;background:transparent;color:inherit;text-align:left;cursor:pointer}.v2-player-heading strong,.v2-player-heading small{display:block}.v2-player-heading small{color:var(--v2-muted,#526078);margin-top:5px}.v2-player-avatar{width:48px;height:52px;border-radius:10px;display:grid;place-items:center;background:var(--v2-canvas,#f3f5f8);font-weight:750;flex-shrink:0;overflow:hidden}.v2-player-avatar img{width:100%;height:100%;object-fit:cover}.v2-player-fields{padding:0 20px 20px}.v2-check{display:flex;align-items:center;gap:10px;min-height:44px;font-size:14px}.v2-media-preview{display:flex;align-items:center;gap:16px;flex-wrap:wrap}.v2-media-preview img{width:112px;height:112px;object-fit:contain;border-radius:10px;border:1px solid var(--v2-line,#dce2e9)}.v2-roster-schema{max-width:320px}.v2-sponsor-logo{height:64px;width:90px;padding:8px;display:grid;place-items:center;background:#fff;border:1px solid var(--v2-line,#dce2e9);border-radius:10px}.v2-sponsor-logo img{max-width:100%;max-height:100%;object-fit:contain}.v2-coupon-metrics{display:flex;gap:22px;flex-wrap:wrap;color:var(--v2-muted,#526078);font-size:13px;padding-top:8px}.v2-coupon-metrics strong{color:var(--v2-ink,#182238)}.v2-save-bar{position:sticky;bottom:16px;z-index:3;box-shadow:0 4px 24px #18223812}.v2-notice{margin:0;padding:16px 20px;background:#fff6df;color:#745014;border:1px solid #ecd698;border-radius:12px}.v2-error{color:#a32135}.v2-success{color:#116443}@media(max-width:600px){.v2-section-heading{align-items:flex-start;flex-direction:column}.v2-search{max-width:none;width:100%}.v2-player-heading{gap:10px;padding:14px}.v2-player-heading .v2-badge{max-width:85px;white-space:normal;font-size:11px}.v2-save-bar{bottom:8px}.v2-save-bar .v2-button{width:100%}.v2-coupon-metrics{gap:12px}}
</style>
